mapper.select:
/*SQL-ID : 월별 내담자 */ WITH ZZ AS (
) , Z1 AS (
) SELECT /* SQL-ID : 월별 내담자*/ FF.CMMNS_CD_VALUE_NM AS BBSCTT_TITLE , EE.* FROM ( SELECT * FROM Z1 PIVOT ( SUM( CCNT ) FOR YYYYMM IN
'${item}' AS ${item}
) ) EE , ( SELECT AA.* FROM SAC100 AA WHERE 1=1 AND AA.CMMNS_CD_ID = 'MM_DSCSN_STATS_TYPE_SE_CD' /* 월상담통계유형구분코드 */ ) FF WHERE 1=1 AND EE.BBSCTT_TYPE_SE_CD(+) = FF.CMMNS_CD_VALUE AND FF.CMMNS_CD_VALUE NOT IN ('24-08','24-02','24-07','24-05','24-06') ORDER BY FF.SRTNG_SQNCE

/*SQL-ID : 월별 상담자 */ WITH ZZ AS (
) , Z1 AS (
) SELECT /* SQL-ID : 월별 상담자*/ FF.CMMNS_CD_VALUE_NM AS BBSCTT_TITLE , EE.* FROM ( SELECT * FROM Z1 PIVOT ( SUM( CCNT ) FOR YYYYMM IN
'${item}' AS ${item}
) ) EE , ( SELECT AA.* FROM SAC100 AA WHERE 1=1 AND AA.CMMNS_CD_ID = 'MM_DSCSN_STATS_TYPE_SE_CD' /* 월상담통계유형구분코드 */ ) FF WHERE 1=1 AND EE.BBSCTT_TYPE_SE_CD(+) = FF.CMMNS_CD_VALUE AND FF.CMMNS_CD_VALUE NOT IN ('24-08','24-02','24-07','24-05','24-06') ORDER BY FF.SRTNG_SQNCE

/*SQL-ID : 월별 내담자 채팅 */ WITH ZZ AS (
) , Z1 AS (
) SELECT /* SQL-ID : 월별 내담자*/ FF.CMMNS_CD_VALUE_NM AS BBSCTT_TITLE , EE.* FROM ( SELECT * FROM Z1 PIVOT ( SUM( CCNT ) FOR YYYYMM IN
'${item}' AS ${item}
) ) EE , ( SELECT AA.* FROM SAC100 AA WHERE 1=1 AND AA.CMMNS_CD_ID = 'CHTT_TYPE_SE_CD' /* 채팅유형구분코드 */ ) FF WHERE 1=1 AND EE.CHTT_TYPE_SE_CD(+) = FF.CMMNS_CD_VALUE AND FF.CMMNS_CD_VALUE IN ('08','02','07','05','06') ORDER BY FF.SRTNG_SQNCE
